<?php
require_once __DIR__ . '/includes/header.php';
require_once __DIR__ . '/includes/auth.php';
$token = getParam('token', ''); $error = ''; $success = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && Auth::verifyCSRFToken(postParam('csrf_token'))) { $result = Auth::resetPassword($token, postParam('password'), postParam('confirm_password')); if ($result['success']) $success = 'Password reset successfully. You can now log in.'; else $error = $result['error']; }
?><main class="container py-5"><div class="col-md-6 mx-auto"><h1>Reset Password</h1><?php if ($error): ?><div class="alert alert-danger"><?php echo h($error); ?></div><?php endif; ?><?php if ($success): ?><div class="alert alert-success"><?php echo h($success); ?></div><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo h(Auth::generateCSRFToken()); ?>"><label class="form-label">New password</label><div class="password-field"><input id="reset-password" class="form-control mb-2" type="password" name="password" data-password-rules="#reset-password-rules" required><button type="button" class="password-toggle" data-password-toggle="reset-password" aria-label="Show password"><i class="fas fa-eye"></i></button></div><div id="reset-password-rules" class="password-rules mb-3"><span data-rule="length"><i class="fas fa-check-circle"></i> 8+ characters</span><span data-rule="uppercase"><i class="fas fa-check-circle"></i> Uppercase letter</span><span data-rule="number"><i class="fas fa-check-circle"></i> Number</span><span data-rule="special"><i class="fas fa-check-circle"></i> Special character</span></div><label class="form-label">Confirm password</label><div class="password-field"><input id="reset-confirm-password" class="form-control mb-3" type="password" name="confirm_password" required><button type="button" class="password-toggle" data-password-toggle="reset-confirm-password" aria-label="Show password"><i class="fas fa-eye"></i></button></div><button class="btn btn-primary">Reset Password</button></form><?php endif; ?></div></main><?php require_once __DIR__ . '/includes/footer.php'; ?>
